window.AW_VIEWS = {"views/_template.html":"<!--\n  SCREEN TEMPLATE. Copy this file, rename it to your screen (e.g. views/products.html) and delete this comment.\n  Screen names that already have a route:  products  price-list  technology  gallery  store-locator  support  about  sitemap\n  You own TWO files:  views/<name>.html  and  css/<name>.css.  Do not edit any other file.\n  Open it at:  index.html#/<name>   (with Live Server)\n  Keep the very last line of this file (the closing comment about Live Server) exactly as it is. Never type that tag name anywhere else.\n-->\n<link rel=\"stylesheet\" href=\"css/NAME.css\">\n\n<!-- Every screen starts with a page head -->\n<section class=\"page-head\">\n  <h1 class=\"title split\"><span>Screen title</span></h1>\n  <span class=\"rule reveal\"></span>\n  <p class=\"sub reveal\" style=\"--i:1\">One short line about this screen</p>\n</section>\n\n<!-- Then alternate dark and ivory sections. Reading-heavy = ivory, photo-heavy = dark. -->\n<section class=\"section section--dark\">\n  <div class=\"wrap\">\n    <h2 class=\"title reveal\">Section title</h2>\n    <p class=\"reveal\" style=\"--i:1\">Short text. One idea per block.</p>\n  </div>\n</section>\n\n<section class=\"section section--ivory\">\n  <div class=\"wrap\">\n    <p class=\"eyebrow reveal\">Small label</p>\n    <h2 class=\"title reveal\">Another section</h2>\n  </div>\n</section>\n\n<!-- </body> (keeps VS Code Live Server from cutting this file short; leave it as the last line) -->\n","views/gallery.html":"<link rel=\"stylesheet\" href=\"css/gallery.css\">\n\n<section class=\"page-head\">\n  <h1 class=\"title split\"><span>The <em>Gallery</em></span></h1>\n  <span class=\"rule reveal\"></span>\n  <p class=\"sub reveal\" style=\"--i:1\">A closer look at the collection</p>\n</section>\n\n<!-- A masonry wall: photos keep their own shape and stack in columns, like a photo feed.\n     To add a photo, copy one <a> line (set width/height to the photo's size). Real photos replace the files in assets/img/gallery/ (same names). -->\n<section class=\"section section--void gal-section\">\n  <div class=\"wrap\">\n    <div class=\"gal-grid\" id=\"galGrid\">\n      <a class=\"gal-item reveal-img\" style=\"--i:0\" href=\"assets/img/gallery/g1.svg\" data-full=\"assets/img/gallery/g1.svg\" aria-label=\"Open photo 1\"><img src=\"assets/img/gallery/g1.svg\" width=\"800\" height=\"1000\" alt=\"Gold-rimmed perpetual watch on a dark brown ground\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:1\" href=\"assets/img/gallery/g2.svg\" data-full=\"assets/img/gallery/g2.svg\" aria-label=\"Open photo 2\"><img src=\"assets/img/gallery/g2.svg\" width=\"800\" height=\"800\" alt=\"Skeleton watch showing its movement\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:2\" href=\"assets/img/gallery/g3.svg\" data-full=\"assets/img/gallery/g3.svg\" aria-label=\"Open photo 3\"><img src=\"assets/img/gallery/g3.svg\" width=\"800\" height=\"1200\" alt=\"Diver watch with a deep blue dial\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:0\" href=\"assets/img/gallery/g4.svg\" data-full=\"assets/img/gallery/g4.svg\" aria-label=\"Open photo 4\"><img src=\"assets/img/gallery/g4.svg\" width=\"800\" height=\"900\" alt=\"Tourbillon watch with a silver case\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:1\" href=\"assets/img/gallery/g5.svg\" data-full=\"assets/img/gallery/g5.svg\" aria-label=\"Open photo 5\"><img src=\"assets/img/gallery/g5.svg\" width=\"800\" height=\"1100\" alt=\"Green aviator watch on a leather strap\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:2\" href=\"assets/img/gallery/g6.svg\" data-full=\"assets/img/gallery/g6.svg\" aria-label=\"Open photo 6\"><img src=\"assets/img/gallery/g6.svg\" width=\"800\" height=\"1000\" alt=\"Cream-dial chronograph with a brown strap\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:0\" href=\"assets/img/gallery/g7.svg\" data-full=\"assets/img/gallery/g7.svg\" aria-label=\"Open photo 7\"><img src=\"assets/img/gallery/g7.svg\" width=\"800\" height=\"1300\" alt=\"Titanium smart watch\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:1\" href=\"assets/img/gallery/g8.svg\" data-full=\"assets/img/gallery/g8.svg\" aria-label=\"Open photo 8\"><img src=\"assets/img/gallery/g8.svg\" width=\"800\" height=\"800\" alt=\"Slim dress watch with an ivory dial\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:2\" href=\"assets/img/gallery/g9.svg\" data-full=\"assets/img/gallery/g9.svg\" aria-label=\"Open photo 9\"><img src=\"assets/img/gallery/g9.svg\" width=\"800\" height=\"1100\" alt=\"Racing chronograph with a red bezel\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:0\" href=\"assets/img/gallery/g10.svg\" data-full=\"assets/img/gallery/g10.svg\" aria-label=\"Open photo 10\"><img src=\"assets/img/gallery/g10.svg\" width=\"800\" height=\"900\" alt=\"Green solar trail watch\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:1\" href=\"assets/img/gallery/g11.svg\" data-full=\"assets/img/gallery/g11.svg\" aria-label=\"Open photo 11\"><img src=\"assets/img/gallery/g11.svg\" width=\"800\" height=\"1200\" alt=\"Smart watch with a sand-coloured strap\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:2\" href=\"assets/img/gallery/g12.svg\" data-full=\"assets/img/gallery/g12.svg\" aria-label=\"Open photo 12\"><img src=\"assets/img/gallery/g12.svg\" width=\"800\" height=\"1000\" alt=\"Black smart watch with a blue accent\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:0\" href=\"assets/img/gallery/g13.svg\" data-full=\"assets/img/gallery/g13.svg\" aria-label=\"Open photo 13\"><img src=\"assets/img/gallery/g13.svg\" width=\"800\" height=\"850\" alt=\"Tourbillon watch in warm light\" loading=\"lazy\"></a>\n      <a class=\"gal-item reveal-img\" style=\"--i:1\" href=\"assets/img/gallery/g14.svg\" data-full=\"assets/img/gallery/g14.svg\" aria-label=\"Open photo 14\"><img src=\"assets/img/gallery/g14.svg\" width=\"800\" height=\"1150\" alt=\"Chronograph on a deep green ground\" loading=\"lazy\"></a>\n    </div>\n  </div>\n</section>\n\n<!-- Viewer: js/gallery.js fills and shows it -->\n<div class=\"gal-viewer\" id=\"galViewer\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Photo viewer\" hidden>\n  <button class=\"gal-x\" type=\"button\" aria-label=\"Close viewer\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M4 4l16 16M20 4L4 20\"/></svg></button>\n  <button class=\"gal-nav gal-prev\" type=\"button\" aria-label=\"Previous photo\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M15 5l-7 7 7 7\"/></svg></button>\n  <button class=\"gal-nav gal-next\" type=\"button\" aria-label=\"Next photo\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M9 5l7 7-7 7\"/></svg></button>\n  <figure class=\"gal-stage\"><img id=\"galImg\" src=\"\" alt=\"\"></figure>\n  <p class=\"gal-count\" id=\"galCount\" aria-live=\"polite\"></p>\n</div>\n\n<!-- </body> (keeps VS Code Live Server from cutting this file short; leave it as the last line) -->\n","views/home.html":"<!-- HOME screen (owner: Obash). Loaded into #app by js/router.js -->\n\n<!-- STAGE: one video sits behind the hero AND the collections. It dims and pauses as you scroll. -->\n<div class=\"stage\" data-stage>\n  <div class=\"stage-media\" aria-hidden=\"true\">\n    <div class=\"hero-poster\"></div>\n    <video class=\"hero-video\" muted loop playsinline preload=\"metadata\">\n      <source src=\"assets/video/hero.mp4\" type=\"video/mp4\">\n    </video>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"stage-dim\" data-stage-dim></div>\n  </div>\n\n  <!-- 1. HERO: an invitation, no button -->\n  <section class=\"hero\" data-hero>\n    <div class=\"hero-content\" data-hero-content>\n      <h1 class=\"hero-title\">Time, perfected.</h1>\n      <p class=\"hero-text\">Step inside and find the watch that is yours.</p>\n    </div>\n    <span class=\"hero-cue\" aria-hidden=\"true\"></span>\n  </section>\n\n  <!-- 2. OUR COLLECTIONS: a pinned scroll scene in two parts (js/motion.js, \"scene\").\n          Part 1: heading appears alone on the dimmed video.  Part 2: heading moves up, the 4 cards slide in one after another.\n          It follows the scroll in both directions, so it always plays. -->\n  <section class=\"collections\" data-scene>\n    <div class=\"collections-pin\" data-scene-pin>\n      <div class=\"wrap\">\n        <div class=\"center collections-head\" data-scene-head>\n          <h2 class=\"title\">Our <em>Collections</em></h2>\n          <span class=\"rule\"></span>\n          <p class=\"sub\">Three ways to tell time</p>\n        </div>\n        <div class=\"collections-grid\">\n          <a class=\"coll-card\" data-scene-card href=\"#/products?line=vintage\">\n            <div class=\"coll-img\"><img src=\"assets/img/collections/vintage.svg\" alt=\"Vintage watch\" loading=\"lazy\"></div>\n            <h3>Vintage</h3><p>Restored classics from past decades.</p>\n          </a>\n          <a class=\"coll-card\" data-scene-card href=\"#/products?line=luxury\">\n            <div class=\"coll-img\"><img src=\"assets/img/collections/luxury.svg\" alt=\"Luxury watch\" loading=\"lazy\"></div>\n            <h3>Luxury</h3><p>Complications and fine finishing.</p>\n          </a>\n          <a class=\"coll-card\" data-scene-card href=\"#/products?line=smart\">\n            <div class=\"coll-img\"><img src=\"assets/img/collections/smart.svg\" alt=\"Smart watch\" loading=\"lazy\"></div>\n            <h3>Smart Watches</h3><p>Sensors and screens, made slim.</p>\n          </a>\n        </div>\n      </div>\n    </div>\n  </section>\n</div>\n\n<!-- 3. FEATURED WATCHES: carousel. Cards are drawn by js/home.js from data/watches.json (watches marked \"featured\") -->\n<section class=\"section section--deep section--void\">\n  <div class=\"wrap featured-grid\" data-play-in-view>\n    <div class=\"featured-head\">\n      <h2 class=\"featured-title\"><span class=\"split\"><span>Featured</span></span><span class=\"split\" style=\"--i:1\"><span><em>Watches</em></span></span></h2>\n      <span class=\"featured-line reveal\"></span>\n    </div>\n    <div class=\"featured-body\">\n      <div class=\"carousel\" id=\"featuredRow\" aria-label=\"Featured watches\"></div>\n      <div class=\"featured-foot reveal\">\n        <div class=\"car-arrows\">\n          <button class=\"car-btn\" id=\"fPrev\" type=\"button\" aria-label=\"Previous watches\"><svg viewBox=\"0 0 18 10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\"><path d=\"M18 5H2M6 1L2 5l4 4\"/></svg></button>\n          <button class=\"car-btn\" id=\"fNext\" type=\"button\" aria-label=\"Next watches\"><svg viewBox=\"0 0 18 10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\"><path d=\"M0 5h16M12 1l4 4-4 4\"/></svg></button>\n        </div>\n        <a class=\"link-line\" href=\"#/products\">Discover more</a>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 4. SERVICES (dark) -->\n<section class=\"section section--deep section--void\">\n  <div class=\"wrap\">\n    <div class=\"services-head\">\n      <div>\n        <p class=\"eyebrow reveal\">What we do</p>\n        <h2 class=\"title split\"><span>Our <em>Services</em></span></h2>\n      </div>\n      <p class=\"services-intro reveal\" style=\"--i:1\">From a battery change to a full restoration, every watch is looked after at our own workshop.</p>\n    </div>\n    <div class=\"svc-grid\">\n      <a class=\"svc-card reveal reveal--up\" style=\"--i:0\" href=\"#/support?section=services\">\n        <div class=\"svc-img\"><img src=\"assets/img/services/repair.svg\" alt=\"A watchmaker's bench with brass gears\" loading=\"lazy\"></div>\n        <h3>Repair</h3>\n        <p>Movements serviced, cases restored and crystals replaced.</p>\n        <span class=\"link-line\">Discover more</span>\n      </a>\n      <a class=\"svc-card reveal reveal--up\" style=\"--i:1\" href=\"#/support?section=services\">\n        <div class=\"svc-img\"><img src=\"assets/img/services/appraisal.svg\" alt=\"A loupe held over a watch face\" loading=\"lazy\"></div>\n        <h3>Appraisal</h3>\n        <p>A clear written valuation for insurance, resale or peace of mind.</p>\n        <span class=\"link-line\">Discover more</span>\n      </a>\n      <a class=\"svc-card reveal reveal--up\" style=\"--i:2\" href=\"#/support?section=services\">\n        <div class=\"svc-img\"><img src=\"assets/img/services/servicing.svg\" alt=\"A balance wheel and hairspring\" loading=\"lazy\"></div>\n        <h3>Servicing</h3>\n        <p>Cleaning, lubrication and water-resistance testing to keep a watch running well.</p>\n        <span class=\"link-line\">Discover more</span>\n      </a>\n      <a class=\"svc-card reveal reveal--up\" style=\"--i:3\" href=\"#/products\">\n        <div class=\"svc-img\"><img src=\"assets/img/services/retail.svg\" alt=\"A watch on a plinth in a display window\" loading=\"lazy\"></div>\n        <h3>Retail</h3>\n        <p>New and pre-owned watches from our three collections.</p>\n        <span class=\"link-line\">Browse watches</span>\n      </a>\n    </div>\n  </div>\n</section>\n\n<!-- 5. WINDOW: transparent gap. The photo stays fixed while the page slides over it. -->\n<section class=\"window\" aria-hidden=\"true\"><div class=\"window-bg\"></div></section>\n\n<!-- 6. GALLERY teaser: call to action to the Gallery screen -->\n<section class=\"section section--deep\">\n  <div class=\"wrap\">\n    <div class=\"center\">\n      <h2 class=\"title\">Gallery</h2>\n      <span class=\"rule\"></span>\n      <p class=\"sub\">A closer look at the watches and the workshop</p>\n    </div>\n    <div class=\"gallery-tiles\">\n      <a class=\"g-tile g-a\" href=\"#/gallery\" aria-label=\"Open the gallery\"><img src=\"assets/img/gallery/g1.svg\" alt=\"\" loading=\"lazy\"></a>\n      <a class=\"g-tile g-b\" href=\"#/gallery\" aria-label=\"Open the gallery\"><img src=\"assets/img/gallery/g3.svg\" alt=\"\" loading=\"lazy\"></a>\n      <a class=\"g-tile g-main\" href=\"#/gallery\" aria-label=\"Open the gallery\"><img src=\"assets/img/gallery/g2.svg\" alt=\"\" loading=\"lazy\"></a>\n      <a class=\"g-tile g-d\" href=\"#/gallery\" aria-label=\"Open the gallery\"><img src=\"assets/img/gallery/g4.svg\" alt=\"\" loading=\"lazy\"></a>\n      <a class=\"g-tile g-e\" href=\"#/gallery\" aria-label=\"Open the gallery\"><img src=\"assets/img/gallery/g5.svg\" alt=\"\" loading=\"lazy\"></a>\n    </div>\n    <div class=\"gallery-cta\">\n      <a class=\"btn-gold\" href=\"#/gallery\">Explore the gallery\n        <svg viewBox=\"0 0 18 10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\"><path d=\"M0 5h16M12 1l4 4-4 4\"/></svg></a>\n    </div>\n  </div>\n</section>\n\n<!-- </body> (keeps VS Code Live Server from cutting this file short; leave it as the last line) -->\n","views/price-list.html":"<link rel=\"stylesheet\" href=\"css/price-list.css\">\n\n<section class=\"page-head\">\n  <h1 class=\"title split\"><span>Price <em>List</em></span></h1>\n  <span class=\"rule reveal\"></span>\n  <p class=\"sub reveal\" style=\"--i:1\">Every watch, in US dollars</p>\n</section>\n\n<section class=\"section section--dark pl-section\">\n  <div class=\"wrap\">\n\n    <!-- Plain facts, nothing invented -->\n    <dl class=\"pl-facts\">\n      <div><dt>Currency</dt><dd class=\"is-gold\">US dollars (USD)</dd></div>\n      <div><dt>Collections</dt><dd>Vintage &middot; Luxury &middot; Smart Watches</dd></div>\n      <div><dt>Available in</dt><dd>Lagos &middot; Abuja &middot; Port Harcourt</dd></div>\n    </dl>\n\n    <!-- Line-up tabs + search -->\n    <div class=\"pl-bar\">\n      <ul class=\"pl-tabs\" id=\"plTabs\">\n        <li><button class=\"pl-tab active\" type=\"button\" data-line=\"all\" aria-pressed=\"true\">All watches<span class=\"pl-n\"></span></button></li>\n        <li><button class=\"pl-tab\" type=\"button\" data-line=\"vintage\" aria-pressed=\"false\">Vintage<span class=\"pl-n\"></span></button></li>\n        <li><button class=\"pl-tab\" type=\"button\" data-line=\"luxury\" aria-pressed=\"false\">Luxury<span class=\"pl-n\"></span></button></li>\n        <li><button class=\"pl-tab\" type=\"button\" data-line=\"smart\" aria-pressed=\"false\">Smart Watches<span class=\"pl-n\"></span></button></li>\n      </ul>\n      <div class=\"pl-search\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"6.5\"/><path d=\"M16 16l4.5 4.5\"/></svg>\n        <input type=\"search\" id=\"priceSearch\" placeholder=\"Filter by name or ref\" aria-label=\"Search the price list\" autocomplete=\"off\" spellcheck=\"false\">\n        <button class=\"pl-clear\" type=\"button\" id=\"priceSearchClear\" aria-label=\"Clear search\" hidden>\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n        </button>\n      </div>\n    </div>\n\n    <!-- The rows are drawn from data/watches.json, so the prices always match the rest of the site -->\n    <div class=\"pl-wrap\">\n      <table class=\"table-lux pl-table\" id=\"priceTable\">\n        <thead>\n          <tr>\n            <th class=\"pl-c-photo\" scope=\"col\">Photo</th>\n            <th scope=\"col\" aria-sort=\"none\"><button class=\"pl-sort\" type=\"button\" data-sort=\"name\">Reference &amp; model</button></th>\n            <th class=\"pl-c-line\" scope=\"col\">Collection</th>\n            <th class=\"pl-c-move\" scope=\"col\">Movement / case</th>\n            <th class=\"pl-c-year\" scope=\"col\" aria-sort=\"none\"><button class=\"pl-sort\" type=\"button\" data-sort=\"year\">Year</button></th>\n            <th class=\"pl-c-price\" scope=\"col\" aria-sort=\"none\"><button class=\"pl-sort\" type=\"button\" data-sort=\"price\">Price</button></th>\n            <th class=\"pl-c-act\" scope=\"col\">Action</th>\n          </tr>\n        </thead>\n        <tbody id=\"priceBody\"></tbody>\n      </table>\n    </div>\n\n    <p class=\"pl-count\" id=\"plCount\" aria-live=\"polite\"></p>\n    <p class=\"pl-note\">Select a watch to see its details.</p>\n  </div>\n</section>\n\n<!-- </body> (keeps VS Code Live Server from cutting this file short; leave it as the last line) -->\n","views/products.html":"<link rel=\"stylesheet\" href=\"css/products.css\">\n\n<section class=\"page-head\">\n  <h1 class=\"title split\"><span>Our <em>Watches</em></span></h1>\n  <span class=\"rule reveal\"></span>\n  <p class=\"sub reveal\" style=\"--i:1\" id=\"prodSub\">All collections</p>\n</section>\n\n<section class=\"section section--charcoal prod-section\">\n  <div class=\"wrap prod-layout\">\n\n    <!-- Filters: left sidebar on desktop, a \"Filters\" button on phones -->\n    <aside class=\"pf\" aria-label=\"Filters\">\n      <button class=\"pf-toggle\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#pfBody\" aria-expanded=\"false\" aria-controls=\"pfBody\">\n        <span>Filters</span>\n        <svg viewBox=\"0 0 12 12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" aria-hidden=\"true\"><path d=\"M6 1v10M1 6h10\"/></svg>\n      </button>\n\n      <div class=\"pf-body collapse\" id=\"pfBody\">\n        <div class=\"pf-head\">\n          <h2 class=\"pf-title\">Filters</h2>\n          <button class=\"pf-reset\" type=\"button\" id=\"pfReset\">Reset</button>\n        </div>\n\n        <fieldset class=\"pf-group\">\n          <legend class=\"pf-label\">Collection</legend>\n          <label class=\"pf-check check-lux\"><input class=\"form-check-input\" type=\"checkbox\" data-line=\"vintage\"><span class=\"pf-name\">Vintage</span><span class=\"pf-n\" data-count=\"vintage\"></span></label>\n          <label class=\"pf-check check-lux\"><input class=\"form-check-input\" type=\"checkbox\" data-line=\"luxury\"><span class=\"pf-name\">Luxury</span><span class=\"pf-n\" data-count=\"luxury\"></span></label>\n          <label class=\"pf-check check-lux\"><input class=\"form-check-input\" type=\"checkbox\" data-line=\"smart\"><span class=\"pf-name\">Smart Watches</span><span class=\"pf-n\" data-count=\"smart\"></span></label>\n        </fieldset>\n\n        <div class=\"pf-group\">\n          <div class=\"pf-row\">\n            <label class=\"pf-label\" for=\"priceRange\">Price ceiling</label>\n            <output class=\"pf-val\" id=\"priceOut\" for=\"priceRange\" aria-live=\"polite\">All prices</output>\n          </div>\n          <input type=\"range\" id=\"priceRange\" min=\"0\" max=\"100\" step=\"1\" value=\"100\">\n          <div class=\"pf-ticks\" aria-hidden=\"true\"><span id=\"priceMin\"></span><span id=\"priceMax\"></span></div>\n        </div>\n\n        <div class=\"pf-group pf-group--last\">\n          <label class=\"pf-label\" for=\"sortBy\">Order</label>\n          <select id=\"sortBy\">\n            <option value=\"default\">Collection</option>\n            <option value=\"price-asc\">Price, low to high</option>\n            <option value=\"price-desc\">Price, high to low</option>\n            <option value=\"name\">Name, A to Z</option>\n          </select>\n        </div>\n      </div>\n    </aside>\n\n    <!-- Results -->\n    <div class=\"prod-main\">\n      <div class=\"prod-bar\">\n        <div class=\"ps\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"6.5\"/><path d=\"M16 16l4.5 4.5\"/></svg>\n          <input type=\"search\" id=\"prodSearch\" placeholder=\"Search watches\" aria-label=\"Search watches\" autocomplete=\"off\" spellcheck=\"false\">\n          <button class=\"ps-clear\" type=\"button\" id=\"prodSearchClear\" aria-label=\"Clear search\" hidden>\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n          </button>\n        </div>\n        <p class=\"prod-count\" id=\"prodCount\" aria-live=\"polite\"></p>\n      </div>\n      <div class=\"prod-grid\" id=\"productGrid\"></div>\n    </div>\n\n  </div>\n</section>\n\n<!-- </body> (keeps VS Code Live Server from cutting this file short; leave it as the last line) -->\n","views/store-locator.html":"<link rel=\"stylesheet\" href=\"css/store-locator.css\">\n\n<section class=\"page-head\">\n  <h1 class=\"title split\"><span>Find <em>Us</em></span></h1>\n  <span class=\"rule reveal\"></span>\n  <p class=\"sub reveal\" style=\"--i:1\">Stores in Abuja, Lagos and Port Harcourt</p>\n</section>\n\n<!-- ============ STORE LOCATOR ============ -->\n<section class=\"section section--ivory sl-section\">\n  <div class=\"wrap\">\n\n    <ul class=\"nav nav-lux sl-tabs reveal\" id=\"slTabs\">\n      <li><button class=\"nav-link\" type=\"button\" data-city=\"abuja\" aria-pressed=\"false\">Abuja</button></li>\n      <li><button class=\"nav-link active\" type=\"button\" data-city=\"lagos\" aria-pressed=\"true\">Lagos</button></li>\n      <li><button class=\"nav-link\" type=\"button\" data-city=\"port-harcourt\" aria-pressed=\"false\">Port Harcourt</button></li>\n    </ul>\n\n    <div class=\"sl-grid\">\n\n      <!-- Details for the chosen city (one at a time) -->\n      <div class=\"sl-info reveal\" style=\"--i:1\">\n        <article class=\"sl-pane\" data-city=\"abuja\">\n          <h2 class=\"title\">Abuja <em>Store</em></h2>\n          <dl class=\"sl-details\">\n            <div><dt>Address</dt><dd>Ceddi Plaza, Tafawa Balewa Way,<br>Central Business District, Abuja</dd></div>\n            <div><dt>Phone</dt><dd><a href=\"tel:+2348000000102\">+234 800 000 0102</a></dd></div>\n            <div><dt>Email</dt><dd><a href=\"mailto:info@albertowatch.com\">info@albertowatch.com</a></dd></div>\n            <div><dt>Hours</dt><dd>Mon &ndash; Sat, 9:00 &ndash; 18:00</dd></div>\n          </dl>\n          <a class=\"link-line\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Ceddi%20Plaza%2C%20Tafawa%20Balewa%20Way%2C%20Central%20Business%20District%2C%20Abuja\">Get directions</a>\n        </article>\n\n        <article class=\"sl-pane\" data-city=\"lagos\">\n          <h2 class=\"title\">Lagos <em>Store</em></h2>\n          <dl class=\"sl-details\">\n            <div><dt>Address</dt><dd>22 Adeola Odeku Street,<br>Victoria Island, Lagos</dd></div>\n            <div><dt>Phone</dt><dd><a href=\"tel:+2348000000102\">+234 800 000 0102</a></dd></div>\n            <div><dt>Email</dt><dd><a href=\"mailto:info@albertowatch.com\">info@albertowatch.com</a></dd></div>\n            <div><dt>Hours</dt><dd>Mon &ndash; Sat, 9:00 &ndash; 18:00</dd></div>\n          </dl>\n          <a class=\"link-line\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/maps/search/?api=1&amp;query=22%20Adeola%20Odeku%20Street%2C%20Victoria%20Island%2C%20Lagos\">Get directions</a>\n        </article>\n\n        <article class=\"sl-pane\" data-city=\"port-harcourt\">\n          <h2 class=\"title\">Port Harcourt <em>Store</em></h2>\n          <dl class=\"sl-details\">\n            <div><dt>Address</dt><dd>Port Harcourt Pleasure Park,<br>Port Harcourt</dd></div>\n            <div><dt>Phone</dt><dd><a href=\"tel:+2348000000102\">+234 800 000 0102</a></dd></div>\n            <div><dt>Email</dt><dd><a href=\"mailto:info@albertowatch.com\">info@albertowatch.com</a></dd></div>\n            <div><dt>Hours</dt><dd>Mon &ndash; Sat, 9:00 &ndash; 18:00</dd></div>\n          </dl>\n          <a class=\"link-line\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Port%20Harcourt%20Pleasure%20Park%2C%20Port%20Harcourt\">Get directions</a>\n        </article>\n      </div>\n\n      <!-- Map box: a drawn street map for each city, the pin marks the store -->\n      <div class=\"sl-map reveal\" style=\"--i:2\" id=\"storeMap\">\n        <iframe data-city=\"abuja\" title=\"Map showing the Abuja store\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\" src=\"https://www.google.com/maps?q=Ceddi%20Plaza%2C%20Tafawa%20Balewa%20Way%2C%20Central%20Business%20District%2C%20Abuja&amp;output=embed\" hidden></iframe>\n        <iframe data-city=\"lagos\" title=\"Map showing the Victoria Island, Lagos store\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\" src=\"https://www.google.com/maps?q=22%20Adeola%20Odeku%20Street%2C%20Victoria%20Island%2C%20Lagos&amp;output=embed\"></iframe>\n        <iframe data-city=\"port-harcourt\" title=\"Map showing the Port Harcourt store\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\" src=\"https://www.google.com/maps?q=Port%20Harcourt%20Pleasure%20Park%2C%20Port%20Harcourt&amp;output=embed\" hidden></iframe>\n      </div>\n\n    </div>\n  </div>\n</section>\n\n<!-- ============ CONTACT ============ -->\n<section class=\"section section--dark sl-contact\" id=\"contactSection\">\n  <div class=\"wrap sl-contact-grid\">\n\n    <div class=\"sl-contact-intro\">\n      <h2 class=\"title reveal\">Send an <em>Enquiry</em></h2>\n      <span class=\"rule rule--left reveal\"></span>\n      <p class=\"reveal\" style=\"--i:1\">Ask about a watch, a repair or a valuation.</p>\n      <ul class=\"sl-direct reveal\" style=\"--i:2\">\n        <li><span>Email</span><a href=\"mailto:info@albertowatch.com\">info@albertowatch.com</a></li>\n        <li><span>Phone</span><a href=\"tel:+2348000000102\">+234 800 000 0102</a></li>\n        <li><span>Head store</span>22 Adeola Odeku Street, Victoria Island, Lagos</li>\n      </ul>\n    </div>\n\n    <div class=\"sl-formwrap reveal\" style=\"--i:1\">\n      <form id=\"contactForm\" novalidate>\n        <div class=\"sl-row\">\n          <div class=\"field\"><label for=\"cfName\">Name</label><input id=\"cfName\" name=\"name\" type=\"text\" autocomplete=\"name\" maxlength=\"60\" aria-describedby=\"cfNameErr\"><span class=\"error\" id=\"cfNameErr\" aria-live=\"polite\"></span></div>\n          <div class=\"field\"><label for=\"cfEmail\">Email</label><input id=\"cfEmail\" name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"80\" aria-describedby=\"cfEmailErr\"><span class=\"error\" id=\"cfEmailErr\" aria-live=\"polite\"></span></div>\n        </div>\n        <div class=\"sl-row\">\n          <div class=\"field\"><label for=\"cfPhone\">Phone (optional)</label><input id=\"cfPhone\" name=\"phone\" type=\"tel\" autocomplete=\"tel\" maxlength=\"24\" aria-describedby=\"cfPhoneErr\"><span class=\"error\" id=\"cfPhoneErr\" aria-live=\"polite\"></span></div>\n          <div class=\"field\"><label for=\"cfStore\">Preferred store</label>\n            <select id=\"cfStore\" name=\"store\">\n              <option value=\"\">Any store</option>\n              <option value=\"Abuja\">Abuja</option>\n              <option value=\"Lagos\">Lagos</option>\n              <option value=\"Port Harcourt\">Port Harcourt</option>\n            </select><span class=\"error\"></span></div>\n        </div>\n        <div class=\"field\"><label for=\"cfTopic\">Topic</label>\n          <select id=\"cfTopic\" name=\"topic\" aria-describedby=\"cfTopicErr\">\n            <option value=\"\">Choose a topic</option>\n            <option value=\"General question\">General question</option>\n            <option value=\"A watch\">A watch</option>\n            <option value=\"Repair or servicing\">Repair or servicing</option>\n            <option value=\"Appraisal\">Appraisal</option>\n          </select><span class=\"error\" id=\"cfTopicErr\" aria-live=\"polite\"></span></div>\n        <div class=\"field\"><label for=\"cfMsg\">Message</label><textarea id=\"cfMsg\" name=\"message\" maxlength=\"1000\" aria-describedby=\"cfMsgErr\"></textarea><span class=\"error\" id=\"cfMsgErr\" aria-live=\"polite\"></span></div>\n        <button class=\"btn-gold\" type=\"submit\">Send message\n          <svg viewBox=\"0 0 18 10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" aria-hidden=\"true\"><path d=\"M0 5h16M12 1l4 4-4 4\"/></svg></button>\n      </form>\n\n      <!-- shown after a valid send -->\n      <div class=\"sl-done\" id=\"contactDone\" tabindex=\"-1\" hidden>\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M7.5 12.5l3 3 6-6.5\"/></svg>\n        <h3 class=\"title\" id=\"doneTitle\">Thank you</h3>\n        <p id=\"doneText\"></p>\n        <button class=\"link-line\" type=\"button\" id=\"contactAgain\">Send another message</button>\n      </div>\n    </div>\n\n  </div>\n</section>\n\n<!-- </body> (keeps VS Code Live Server from cutting this file short; leave it as the last line) -->\n","views/technology.html":"<link rel=\"stylesheet\" href=\"css/technology.css\">\n\n<section class=\"page-head\">\n  <h1 class=\"title split\"><span>Watch <em>Technology</em></span></h1>\n  <span class=\"rule reveal\"></span>\n  <p class=\"sub reveal\" style=\"--i:1\">How a watch keeps time</p>\n</section>\n\n<section class=\"section section--ivory tech-section\">\n  <div class=\"wrap tech-layout\">\n\n    <!-- Index: pick a topic (menu links like #/technology?item=solar open it directly) -->\n    <nav class=\"tech-index reveal\" aria-label=\"Technology topics\">\n      <ul class=\"tech-list\" id=\"techList\">\n        <li><button class=\"tech-tab\" type=\"button\" data-key=\"mechanical\"><span class=\"tech-no\">01</span><span>Mechanical</span></button></li>\n        <li><button class=\"tech-tab\" type=\"button\" data-key=\"automatic\"><span class=\"tech-no\">02</span><span>Automatic</span></button></li>\n        <li><button class=\"tech-tab\" type=\"button\" data-key=\"quartz\"><span class=\"tech-no\">03</span><span>Quartz</span></button></li>\n        <li><button class=\"tech-tab\" type=\"button\" data-key=\"solar\"><span class=\"tech-no\">04</span><span>Solar</span></button></li>\n        <li><button class=\"tech-tab\" type=\"button\" data-key=\"smart-sensors\"><span class=\"tech-no\">05</span><span>Smart Sensors</span></button></li>\n      </ul>\n    </nav>\n\n    <!-- Stage: one topic open at a time -->\n    <div class=\"tech-stage reveal\" style=\"--i:1\">\n\n      <!-- 01 MECHANICAL -->\n      <article class=\"tech-item\" data-key=\"mechanical\" id=\"tech-mechanical\">\n        <div class=\"tech-head\">\n          <p class=\"tech-eyebrow\">01 / 05</p>\n          <h2 class=\"title\">Mechanical <em>Movement</em></h2>\n          <p class=\"tech-intro\">A wound spring supplies the power. A balance wheel keeps the beat.</p>\n        </div>\n        <figure class=\"tech-visual\">\n          <svg viewBox=\"0 10 640 290\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" role=\"img\" aria-label=\"A mainspring barrel turning a gear train that drives a swinging balance wheel\">\n            <g class=\"tk-spin\">\n              <circle class=\"tk-teeth\" cx=\"170\" cy=\"165\" r=\"78\" stroke-width=\"9\" stroke-dasharray=\"8.6 5\"/>\n              <circle cx=\"170\" cy=\"165\" r=\"66\"/>\n              <path d=\"M170 165a3 3 0 0 1 6 0a6 6 0 0 1-12 0a9 9 0 0 1 18 0a12 12 0 0 1-24 0a15 15 0 0 1 30 0a18 18 0 0 1-36 0a21 21 0 0 1 42 0a24 24 0 0 1-48 0a27 27 0 0 1 54 0a30 30 0 0 1-60 0\"/>\n              <circle cx=\"170\" cy=\"165\" r=\"5\" fill=\"currentColor\" stroke=\"none\"/>\n            </g>\n            <g class=\"tk-spin tk-rev\">\n              <circle class=\"tk-teeth\" cx=\"290\" cy=\"105\" r=\"46\" stroke-width=\"8\" stroke-dasharray=\"7.4 4.64\"/>\n              <circle cx=\"290\" cy=\"105\" r=\"36\"/>\n              <path d=\"M290 69V141M254 105H326\"/>\n              <circle cx=\"290\" cy=\"105\" r=\"5\" fill=\"currentColor\" stroke=\"none\"/>\n            </g>\n            <g class=\"tk-spin\">\n              <circle class=\"tk-teeth\" cx=\"354\" cy=\"172\" r=\"36\" stroke-width=\"8\" stroke-dasharray=\"7 4.31\"/>\n              <circle cx=\"354\" cy=\"172\" r=\"28\"/>\n              <path d=\"M354 144V200M326 172H382\"/>\n              <circle cx=\"354\" cy=\"172\" r=\"4\" fill=\"currentColor\" stroke=\"none\"/>\n            </g>\n            <path class=\"tk-dim\" d=\"M394 170L452 152\" stroke-dasharray=\"2 5\"/>\n            <g class=\"tk-swing\">\n              <circle cx=\"520\" cy=\"150\" r=\"70\" stroke-width=\"2.2\"/>\n              <path d=\"M520 150V80M520 150L459.4 185M520 150L580.6 185\"/>\n              <circle cx=\"520\" cy=\"80\" r=\"6\" class=\"tk-soft\"/>\n              <circle cx=\"459.4\" cy=\"185\" r=\"6\" class=\"tk-soft\"/>\n              <circle cx=\"580.6\" cy=\"185\" r=\"6\" class=\"tk-soft\"/>\n              <path d=\"M520 150a2 2 0 0 1 4 0a4 4 0 0 1-8 0a6 6 0 0 1 12 0a8 8 0 0 1-16 0a10 10 0 0 1 20 0a12 12 0 0 1-24 0a14 14 0 0 1 28 0a16 16 0 0 1-32 0a18 18 0 0 1 36 0a20 20 0 0 1-40 0\"/>\n              <circle cx=\"520\" cy=\"150\" r=\"5\" fill=\"currentColor\" stroke=\"none\"/>\n            </g>\n          </svg>\n        </figure>\n        <div class=\"tech-detail\">\n          <ol class=\"tech-steps\">\n            <li><b>Wind</b>Turning the crown winds the mainspring and stores energy in it.</li>\n            <li><b>Release</b>A gear train carries the energy to the escapement, which lets it out in tiny, even steps.</li>\n            <li><b>Keep time</b>The balance wheel swings back and forth at a steady rate and moves the hands on.</li>\n          </ol>\n          <a class=\"link-line tech-more\" href=\"#/products?q=manual%20wind\">See watches</a>\n        </div>\n      </article>\n\n      <!-- 02 AUTOMATIC -->\n      <article class=\"tech-item\" data-key=\"automatic\" id=\"tech-automatic\">\n        <div class=\"tech-head\">\n          <p class=\"tech-eyebrow\">02 / 05</p>\n          <h2 class=\"title\"><em>Automatic</em> Winding</h2>\n          <p class=\"tech-intro\">A mechanical watch that winds itself as you move.</p>\n        </div>\n        <figure class=\"tech-visual\">\n          <svg viewBox=\"0 10 640 290\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" role=\"img\" aria-label=\"A weighted rotor swinging inside a watch case and winding a mainspring barrel\">\n            <circle class=\"tk-dim\" cx=\"320\" cy=\"160\" r=\"112\"/>\n            <path class=\"tk-dim\" d=\"M335 160H490\" stroke-dasharray=\"2 5\"/>\n            <g class=\"tk-rotor\">\n              <path class=\"tk-soft\" d=\"M225 160A95 95 0 0 1 415 160L375 160A55 55 0 0 0 265 160Z\"/>\n              <path d=\"M320 160V105\"/>\n            </g>\n            <circle cx=\"320\" cy=\"160\" r=\"8\" fill=\"currentColor\" stroke=\"none\"/>\n            <path class=\"tk-dim\" d=\"M205 70A146 146 0 0 1 435 70M432.7 60.2L435 70L426 65.5M207.3 60.2L205 70L214 65.5\"/>\n            <g class=\"tk-spin\">\n              <circle class=\"tk-teeth\" cx=\"535\" cy=\"160\" r=\"40\" stroke-width=\"8\" stroke-dasharray=\"8.8 5.16\"/>\n              <circle cx=\"535\" cy=\"160\" r=\"31\"/>\n              <path d=\"M535 160a1.5 1.5 0 0 1 3 0a3 3 0 0 1-6 0a4.5 4.5 0 0 1 9 0a6 6 0 0 1-12 0a7.5 7.5 0 0 1 15 0a9 9 0 0 1-18 0a10.5 10.5 0 0 1 21 0a12 12 0 0 1-24 0a13.5 13.5 0 0 1 27 0a15 15 0 0 1-30 0\"/>\n            </g>\n          </svg>\n        </figure>\n        <div class=\"tech-detail\">\n          <ol class=\"tech-steps\">\n            <li><b>Swing</b>A weighted rotor turns freely whenever your wrist moves.</li>\n            <li><b>Wind</b>Through a small gear train, the rotor winds the mainspring for you.</li>\n            <li><b>Run</b>The movement then works like a mechanical one, with no crown winding needed while you wear it.</li>\n          </ol>\n          <a class=\"link-line tech-more\" href=\"#/products?q=automatic\">See watches</a>\n        </div>\n      </article>\n\n      <!-- 03 QUARTZ -->\n      <article class=\"tech-item\" data-key=\"quartz\" id=\"tech-quartz\">\n        <div class=\"tech-head\">\n          <p class=\"tech-eyebrow\">03 / 05</p>\n          <h2 class=\"title\">Quartz <em>Timekeeping</em></h2>\n          <p class=\"tech-intro\">A battery and a crystal, counting time with great regularity.</p>\n        </div>\n        <figure class=\"tech-visual\">\n          <svg viewBox=\"0 10 640 290\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" role=\"img\" aria-label=\"A battery powering a vibrating quartz crystal, a counting circuit and a dial with a ticking second hand\">\n            <rect x=\"40\" y=\"120\" width=\"100\" height=\"64\" rx=\"6\"/>\n            <rect x=\"140\" y=\"140\" width=\"8\" height=\"24\" rx=\"2\"/>\n            <path d=\"M64 152h12M70 146v12M104 152h12\"/>\n            <path d=\"M148 152H220\"/>\n            <rect x=\"220\" y=\"112\" width=\"110\" height=\"80\" rx=\"4\"/>\n            <path d=\"M212 128h8M212 152h8M212 176h8M330 128h8M330 176h8\"/>\n            <path d=\"M275 98V112M262 90V40M288 90V40M262 90Q275 102 288 90\"/>\n            <path class=\"tk-dim tk-vib\" d=\"M252 52q-8 10 0 20M298 52q8 10 0 20M242 48q-12 14 0 28M308 48q12 14 0 28\"/>\n            <path d=\"M330 152H338q9-26 18 0t18 0t18 0t18 0\"/>\n            <path d=\"M410 152H448\"/>\n            <circle cx=\"520\" cy=\"152\" r=\"72\"/>\n            <circle class=\"tk-dim\" cx=\"520\" cy=\"152\" r=\"66\"/>\n            <path d=\"M520 82v8M555 91.4l-4 6.9M580.6 117l-6.9 4M590 152h-8M580.6 187l-6.9-4M555 212.6l-4-6.9M520 222v-8M485 212.6l4-6.9M459.4 187l6.9-4M450 152h8M459.4 117l6.9 4M485 91.4l4 6.9\"/>\n            <path d=\"M520 152L490.6 135M520 152L565 126\"/>\n            <path class=\"tk-tick\" d=\"M520 152V92\"/>\n            <circle cx=\"520\" cy=\"152\" r=\"4\" fill=\"currentColor\" stroke=\"none\"/>\n          </svg>\n        </figure>\n        <div class=\"tech-detail\">\n          <ol class=\"tech-steps\">\n            <li><b>Power</b>A battery sends a small current to a quartz crystal.</li>\n            <li><b>Vibrate</b>The crystal vibrates 32,768 times every second, always at the same rate.</li>\n            <li><b>Count</b>A circuit counts the vibrations and steps the hands once a second.</li>\n          </ol>\n        </div>\n      </article>\n\n      <!-- 04 SOLAR -->\n      <article class=\"tech-item\" data-key=\"solar\" id=\"tech-solar\">\n        <div class=\"tech-head\">\n          <p class=\"tech-eyebrow\">04 / 05</p>\n          <h2 class=\"title\">Solar <em>Power</em></h2>\n          <p class=\"tech-intro\">Light charges a cell, and the cell runs a quartz movement.</p>\n        </div>\n        <figure class=\"tech-visual\">\n          <svg viewBox=\"0 10 640 290\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" role=\"img\" aria-label=\"Sunlight falling on a watch dial with a solar cell, charging a battery\">\n            <circle cx=\"90\" cy=\"70\" r=\"22\"/>\n            <circle cx=\"90\" cy=\"70\" r=\"40\" stroke-width=\"14\" stroke-dasharray=\"1.2 19.74\" stroke-linecap=\"butt\"/>\n            <path class=\"tk-dim tk-flow\" d=\"M125 90L270 125M122 98L262 150M120 106L255 175\" stroke-dasharray=\"4 6\"/>\n            <circle cx=\"360\" cy=\"190\" r=\"100\"/>\n            <circle class=\"tk-dim\" cx=\"360\" cy=\"190\" r=\"92\"/>\n            <circle class=\"tk-cells\" cx=\"360\" cy=\"190\" r=\"66\" stroke-width=\"22\" stroke-dasharray=\"37.47 4\" stroke-linecap=\"butt\"/>\n            <circle cx=\"360\" cy=\"190\" r=\"84\" stroke-width=\"8\" stroke-dasharray=\"1.2 42.78\" stroke-linecap=\"butt\" transform=\"rotate(-90 360 190)\"/>\n            <path d=\"M360 190L323 164M360 190L416 158\"/>\n            <circle cx=\"360\" cy=\"190\" r=\"4\" fill=\"currentColor\" stroke=\"none\"/>\n            <path d=\"M460 190H530\"/>\n            <rect x=\"530\" y=\"150\" width=\"60\" height=\"90\" rx=\"6\"/>\n            <rect x=\"550\" y=\"142\" width=\"20\" height=\"8\" rx=\"2\"/>\n            <path d=\"M540 175H580M540 195H580M540 215H580\" class=\"tk-level\"/>\n          </svg>\n        </figure>\n        <div class=\"tech-detail\">\n          <ol class=\"tech-steps\">\n            <li><b>Collect</b>A solar cell under the dial turns light into electricity.</li>\n            <li><b>Store</b>A rechargeable cell holds that power for when it is dark.</li>\n            <li><b>Run</b>The quartz movement draws on the stored power, so it keeps going after dark and rarely needs a new battery.</li>\n          </ol>\n        </div>\n      </article>\n\n      <!-- 05 SMART SENSORS -->\n      <article class=\"tech-item\" data-key=\"smart-sensors\" id=\"tech-smart-sensors\">\n        <div class=\"tech-head\">\n          <p class=\"tech-eyebrow\">05 / 05</p>\n          <h2 class=\"title\">Smart <em>Sensors</em></h2>\n          <p class=\"tech-intro\">Sensors read your body and your movement, then show the result on the screen.</p>\n        </div>\n        <figure class=\"tech-visual\">\n          <svg viewBox=\"0 10 640 290\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" role=\"img\" aria-label=\"Sensors on the back of a smartwatch reading a pulse and sending the result to a phone\">\n            <rect x=\"160\" y=\"30\" width=\"90\" height=\"30\" rx=\"8\" class=\"tk-dim\"/>\n            <rect x=\"160\" y=\"260\" width=\"90\" height=\"30\" rx=\"8\" class=\"tk-dim\"/>\n            <rect x=\"120\" y=\"60\" width=\"170\" height=\"200\" rx=\"50\"/>\n            <circle cx=\"205\" cy=\"160\" r=\"54\"/>\n            <circle class=\"tk-pulse\" cx=\"205\" cy=\"160\" r=\"54\"/>\n            <circle class=\"tk-soft\" cx=\"205\" cy=\"130\" r=\"7\"/>\n            <circle class=\"tk-soft\" cx=\"180\" cy=\"173\" r=\"7\"/>\n            <circle class=\"tk-soft\" cx=\"230\" cy=\"173\" r=\"7\"/>\n            <circle cx=\"205\" cy=\"160\" r=\"3\" fill=\"currentColor\" stroke=\"none\"/>\n            <path class=\"tk-draw\" d=\"M290 160H330L342 120L358 205L372 140L382 160H470\"/>\n            <rect x=\"470\" y=\"70\" width=\"110\" height=\"180\" rx=\"16\"/>\n            <path class=\"tk-dim\" d=\"M505 84H545\"/>\n            <circle class=\"tk-dim\" cx=\"525\" cy=\"125\" r=\"22\"/>\n            <circle cx=\"525\" cy=\"125\" r=\"22\" stroke-dasharray=\"96 42\" transform=\"rotate(-90 525 125)\"/>\n            <path d=\"M488 205l14-20l14 12l14-30l14 18l14-10\"/>\n          </svg>\n        </figure>\n        <div class=\"tech-detail\">\n          <ol class=\"tech-steps\">\n            <li><b>Sense</b>Light sensors on the case back read your pulse through the skin. An accelerometer and GPS follow your steps and routes.</li>\n            <li><b>Process</b>A small processor turns the raw readings into clear numbers.</li>\n            <li><b>Share</b>The watch shows them on its display and sends them to your phone over Bluetooth.</li>\n          </ol>\n          <a class=\"link-line tech-more\" href=\"#/products?line=smart\">See watches</a>\n        </div>\n      </article>\n\n    </div>\n  </div>\n</section>\n\n<!-- </body> (keeps VS Code Live Server from cutting this file short; leave it as the last line) -->\n"};
